"A GitHub user or organization: every project of it is listed.": "Un usuario u organización de GitHub: se listan todos sus proyectos.",
"A Model Context Protocol server gives a coding agent extra tools: files, the web, a browser, GitHub and the like. This only reaches the agents that sign in through their own command-line tool in Termux (Claude Code, Gemini CLI, Codex, Copilot CLI, Cursor CLI, OpenCode) — an agent used only with an API key cannot use one here.": "Un servidor de Model Context Protocol da a un agente de código herramientas adicionales: archivos, la web, un navegador, GitHub y similares. Esto solo llega a los agentes que inician sesión con su propia herramienta de línea de comandos en Termux (Claude Code, Gemini CLI, Codex, Copilot CLI, Cursor CLI, OpenCode); un agente que se usa solo con una clave de API no puede usar uno aquí.",
"A Wear OS watch can be reached over its Bluetooth link to the phone, with no Wi-Fi. This phone then talks to the watch through its own ADB.": "Un reloj con Wear OS se puede alcanzar mediante su enlace Bluetooth con el teléfono, sin Wi-Fi. Entonces este teléfono se comunica con el reloj a través de su propio ADB.",
