"App: ADB Application Manager Pro ? (build ?)": "App: ADB Application Manager Pro ? (compilación ?)",
"AppCleaner can clear the caches that no file access can reach (the \"Clear cache\" button of an app's Storage screen) by tapping through the system settings for you. For that it needs this app's accessibility service. The service only acts while AppCleaner is clearing caches: it opens the App info screen of one app after the other, taps Clear cache, and stops when the screen turns off or locks. A cover over the screen shows what it is doing, with a way to cancel. Nothing is read or sent anywhere. On Android 13 and newer, an app installed from a file may first need \"Allow restricted settings\" (App info of this app, the three dots menu).": "AppCleaner puede borrar las cachés a las que ningún acceso a archivos llega (el botón «Borrar caché» de la pantalla Almacenamiento de una app) pulsando por ti en los ajustes del sistema. Para eso necesita el servicio de accesibilidad de esta app. El servicio solo actúa mientras AppCleaner borra cachés: abre la pantalla Información de la app de una app tras otra, pulsa Borrar caché y se detiene cuando la pantalla se apaga o se bloquea. Una cubierta sobre la pantalla muestra lo que hace, con una forma de cancelar. No se lee ni se envía nada a ningún sitio. En Android 13 y posteriores, una app instalada desde un archivo puede necesitar primero «Permitir ajustes restringidos» (Información de la app de esta app, menú de tres puntos).",
