"Browser Use": "Browser Use",
"Browser Use is an open-source library that lets an AI model drive a web browser to do a task. It runs on a computer with Python and needs a key for the AI model it uses (its own cloud gives new accounts some free credit, then it is paid). It has no Android version and is not a coding agent, so it does not chat here.": "Browser Use es una biblioteca de código abierto que permite a un modelo de IA manejar un navegador web para hacer una tarea. Funciona en un ordenador con Python y necesita una clave del modelo de IA que use (su nube da algo de crédito gratis a las cuentas nuevas y después es de pago). No tiene versión para Android y no es un agente de programación, así que no chatea aquí.",
"Browser automation. Needs Node and a Chromium download, which can be heavy on a phone.": "Automatización del navegador. Requiere Node y una descarga de Chromium, que puede ser pesada en un teléfono.",
