"Changing the theme and the overlays goes through the shell. Connect one of them in Working Modes, then come back.": "Cambiar el tema y los overlays se hace mediante el shell. Conecta uno en Modos de operación y vuelve.",
"Changing the theme and the overlays goes through the shell. Connect one of them in Working Modes, then come back. The colors in use now are shown without it.": "Cambiar el tema y los overlays se hace mediante el shell. Conecta uno en Modos de operación y vuelve. Los colores en uso se muestran sin él.",
"Changing this can break setup, apps or the system. Only change it if you know what it does.": "Cambiar esto puede romper la configuración, las apps o el sistema. Cámbialo solo si sabes qué hace.",
