"Choose something to send first": "Elige primero qué enviar",
"Choose the APK to patch first": "Primero elige el APK que quieres parchear",
"Choose the ones to send to the device": "Elige los que se enviarán al dispositivo",
"Choose the sign-in method in the agent's Connect sheet. The tools are installed into a Debian environment inside Termux when they have no Android build. This takes several minutes and up to about 1 GB; the providers do not support Android officially, so a tool may not run on every phone.": "Elige el método de inicio de sesión en la hoja de conexión del agente. Las herramientas sin versión para Android se instalan en un entorno Debian dentro de Termux. Esto tarda varios minutos y ocupa hasta 1 GB aproximadamente; los proveedores no admiten Android oficialmente, así que puede que una herramienta no funcione en todos los teléfonos.",
"Choose what the extra button on each row of the Apps list does. It is always an icon, and the ones that change with the app (Enable / Disable, Install / Uninstall, Unsuspend / Suspend) switch their icon and action to match the app's current state.": "Elige qué hace el botón adicional de cada fila de la lista de Apps. Siempre es un icono, y los que cambian según la app (Activar / Desactivar, Instalar / Desinstalar, Quitar suspensión / Suspender) cambian su icono y su acción para coincidir con el estado actual de la app.",
"Choose what to install and which starter files to write": "Elige qué instalar y qué archivos iniciales escribir",
"Choosing a folder needs the app build": "Elegir una carpeta requiere la versión app",
"Choosing files works in the app": "Elegir archivos funciona en la app",
"Chosen:": "Elegido:",
"Classic three-button navigation bar": "Barra de navegación clásica de tres botones",
"Claude": "Claude",
"Claude (Anthropic)": "Claude (Anthropic)",
"Claude Code": "Claude Code",
"Claude Pro or Max and a Google account login may only be used in the providers' own apps: Anthropic and Google do not allow other apps to use those logins. So the Terminal signs you in through the official command-line tools running in Termux, where the provider's own website login opens:": "Las cuentas de Claude Pro o Max y el inicio de sesión con una cuenta de Google solo pueden usarse en las apps de los propios proveedores: Anthropic y Google no permiten que otras apps los usen. Por eso la Terminal inicia tu sesión con las herramientas oficiales de línea de comandos, que se ejecutan en Termux, donde se abre el inicio de sesión web del propio proveedor:",
"Clean up what is not needed any more: superfluous files, the expendable data of apps, the leftovers of apps that are gone, and files that exist twice. Scan first, look at the list, take out what you want to keep, then delete. The four tools use the working mode of this app for the folders a normal app cannot read.": "Limpia lo que ya no hace falta: archivos superfluos, los datos prescindibles de las apps, los restos de apps que ya no están y los archivos que existen dos veces. Primero analiza, mira la lista, quita lo que quieras conservar y luego borra. Las cuatro herramientas usan el modo de operación de esta app para las carpetas que una app normal no puede leer.",
"Clean — no engine flagged this file": "Limpio — ningún motor marcó este archivo",
"Cleanup is simulated. Files are scanned and reported, but nothing is actually deleted.": "La limpieza es simulada. Los archivos se analizan y se informa de ellos, pero en realidad no se borra nada.",
