"Crawl4AI": "Crawl4AI",
"Crawl4AI is an open-source web crawler that turns web pages into clean text for AI models. The library and its Docker server are free, but run on a computer, not on Android; its hosted cloud is pay-as-you-go. It is not a coding agent, so it does not chat here.": "Crawl4AI es un rastreador web de código abierto que convierte páginas web en texto limpio para modelos de IA. La biblioteca y su servidor Docker son gratuitos, pero funcionan en un ordenador, no en Android; su nube alojada se paga por uso. No es un agente de programación, así que no chatea aquí.",
