"EXPERT": "EXPERTO",
"Each agent keeps this in its own file, the same way its official sign-in does, so two or more agents can carry the same server and either can be used with it. Codex keeps a remote server's token as an environment variable instead of in its file. Not tested against every version of every tool.": "Cada agente guarda esto en su propio archivo, igual que su inicio de sesión oficial, de modo que dos o más agentes pueden tener el mismo servidor y cualquiera puede usarlo. Codex guarda el token de un servidor remoto como variable de entorno en lugar de en su archivo. No se probó con todas las versiones de todas las herramientas.",
"Each shell keeps its own screen and stays open while you use other tabs: cd, export and variables carry over from one command to the next. Restart shell starts a fresh one.": "Cada shell conserva su propia pantalla y sigue abierto mientras usas otras pestañas: cd, export y las variables se mantienen de un comando al siguiente. Reiniciar shell inicia uno nuevo.",
"Each wait is 600 seconds (10 minutes) at most.": "Cada espera es de 600 segundos (10 minutos) como máximo.",
"Earlier certificates (the signing key was changed)": "Certificados anteriores (se cambió la clave de firma)",
