"Edited": "Editados",
"Editing an APK changes its contents, so its signature no longer matches. Android will not install it until it is signed again: use Sign (this app signs with a key of its own).": "Editar un APK cambia su contenido, así que su firma ya no coincide. Android no lo instalará hasta que se firme de nuevo: usa Firmar (esta app firma con una clave propia).",
"Editing an APK changes its contents, so its signature no longer matches. Android will not install it until it is signed again; Sign does that with a key of this app.": "Editar un APK cambia su contenido, así que su firma ya no coincide. Android no lo instalará hasta que se firme de nuevo; Firmar lo hace con una clave de esta app.",
"Effort": "Esfuerzo",
"Effort only changes anything for the agents whose own API has that knob (Claude, ChatGPT, Gemini, Grok); for the others it is kept but has no effect when chatting by API key, and none of them pass it on to their own sign-in tool in Termux.": "El esfuerzo solo cambia algo en los agentes cuya API tiene ese control (Claude, ChatGPT, Gemini, Grok); en los demás se conserva, pero no tiene efecto al chatear con una clave de API, y ninguno lo transmite a su propia herramienta de inicio de sesión en Termux.",
