"Every app in the F-Droid catalog, or in any of the known third-party repositories. Pick a repository, browse by category and install directly — downloads are checked against the repository's published SHA-256.": "Todas las apps del catálogo de F-Droid o de cualquiera de los repositorios de terceros conocidos. Elige un repositorio, explora por categoría e instala directamente: las descargas se verifican con el SHA-256 publicado por el repositorio.",
