"For a coding agent that runs right here in Termux instead, choose OpenCode, or one of the API-key / sign-in agents above.": "Para un agente de código que se ejecute aquí mismo, en Termux, elige OpenCode o uno de los agentes con clave de API o inicio de sesión de arriba.",
"For a free assistant on this phone, choose Ollama (on-device); for one on your computer, Jan.ai or AnythingLLM.": "Para un asistente gratuito en este teléfono, elige Ollama (en el dispositivo); para uno en tu computadora, Jan.ai o AnythingLLM.",
"For an answer to an Ask agent button, choose an agent above that has a key or runs on your own server; with none, the button reads the web for you (free, no key).": "Para obtener una respuesta en un botón Preguntar al agente, elige arriba un agente con clave o en tu propio servidor; sin agente, el botón lee la web por ti (gratis, sin clave).",
"Force": "Forzar",
