"Force-stop an app": "Forzar la detención de una app",
"Force-stop apps before clearing their cache. It can help clear some apps' caches, but may cause apps to misbehave and require manual restart.": "Fuerza la detención de las apps antes de borrar su caché. Puede ayudar a borrar la caché de algunas apps, pero puede hacer que las apps funcionen mal y haya que reiniciarlas a mano.",
"Force-stop before clearing": "Forzar detención antes de borrar",
