"Forget the key": "Olvidar la clave",
"Forgotten": "Olvidado",
"Format": "Formato",
"Found by reading the class names in the app's code on this phone; nothing is sent anywhere. Tracker list: Exodus Privacy, licensed ODbL 1.0. Code renamed by a shrinker (R8, ProGuard) or loaded later can hide a tracker, so a low number is not proof that there are none.": "Se encuentran leyendo los nombres de clase en el código de la app en este teléfono; no se envía nada a ningún sitio. Lista de rastreadores: Exodus Privacy, con licencia ODbL 1.0. El código renombrado por un reductor (R8, ProGuard) o cargado más tarde puede ocultar un rastreador, así que un número bajo no prueba que no haya ninguno.",
"Found in Downloads": "Encontrado en Descargas",
"Free": "Libre",
"Free Open-Source": "Gratis y de código abierto",
"Free and open-source": "Gratis y de código abierto",
