"Invalid source URL: the address must point to a GitHub or GitLab repository, or to a .json metadata file.": "URL de fuente no válida: la dirección debe apuntar a un repositorio de GitHub o GitLab, o a un archivo de metadatos .json.",
"Invalid source URL: the address must start with https.": "URL de fuente no válida: la dirección debe empezar por https.",
"Is it safe to disable?": "¿Es seguro desactivarla?",
"Issuer": "Emisor",
"Issues": "Incidencias",
"It could not be saved": "No se pudo guardar",
"It did not finish": "No terminó",
"It did not work": "No funcionó",
"It finishes installing itself the first time it opens.": "Termina de instalarse la primera vez que se abre.",
"It has no Android build, so it goes into a Debian container inside Termux (several minutes, a few hundred MB). Already installed steps are skipped quickly.": "No tiene versión para Android, así que se instala en un contenedor Debian dentro de Termux (varios minutos, unos cientos de MB). Los pasos ya instalados se omiten rápidamente.",
"It has no value right now.": "Ahora mismo no tiene valor.",
"It is connected now and stays connected. It is saved again the next time you connect it.": "Está conectado ahora y sigue conectado. Se guarda de nuevo la próxima vez que lo conectes.",
"It is installed silently through the working mode.": "Se instala en silencio con el modo de operación.",
"It is not set any more": "Ya no está definido",
"It is removed for the device's user. A system app can be put back with Reinstall.": "Se elimina para el usuario del dispositivo. Una app del sistema se puede recuperar con Reinstalar.",
"It is tried as it is first; if Android refuses it, a copy signed with this app's key is installed.": "Primero se intenta tal cual; si Android lo rechaza, se instala una copia firmada con la clave de esta app.",
"It looks like a percentage.": "Parece un porcentaje.",
"It looks like a time in seconds.": "Parece un tiempo en segundos.",
"It looks like a web address.": "Parece una dirección web.",
"It looks like an app component (package/class).": "Parece un componente de app (paquete/clase).",
"It looks like an app package name, or a list of them.": "Parece un nombre de paquete de app, o una lista de ellos.",
"It looks like an on/off switch.": "Parece un interruptor de activado/desactivado.",
"It needs your consent first.": "Primero necesita tu consentimiento.",
"Item": "Elemento",
"Its patches are removed from this phone. Apps you already patched stay as they are.": "Sus parches se quitan de este teléfono. Las apps que ya parcheaste se quedan como están.",
"Its settings, accounts and files on the device are deleted.": "Se eliminan sus ajustes, cuentas y archivos del dispositivo.",
"Its value is a decimal number.": "Su valor es un número decimal.",
"Its value is a whole number.": "Su valor es un número entero.",
"Its value is text.": "Su valor es texto.",
"IzzyOnDroid": "IzzyOnDroid",
"IzzyOnDroid page": "Página de IzzyOnDroid",
"JVM code cache. Blocks of bytecode compiled into native code.": "Caché de código de la JVM. Bloques de bytecode compilados a código nativo.",
"Jan runs AI models on your computer, free. On the computer: Jan, Settings, Local API Server: set the host to 0.0.0.0 and start it, then enter the computer's address here (like http://192.168.1.20:1337/v1). There is no Android version of Jan.": "Jan ejecuta modelos de IA en tu computadora, gratis. En la computadora: Jan, Settings, Local API Server: define el host como 0.0.0.0 e inícialo; luego ingresa aquí la dirección de la computadora (como http://192.168.1.20:1337/v1). Jan no tiene versión para Android.",
"Jan.ai": "Jan.ai",
"Keep": "Conservar",
"Keep a copy of your saved lists in a folder of your choice, and bring them back from a backup file.": "Guarda una copia de tus listas en la carpeta que elijas y recupérala desde un archivo de copia.",
