"Keys and servers": "Claves y servidores",
"Keys are encrypted with a key that stays in the phone's secure hardware, and they are only ever sent to their own provider's address. The page never sees them again after you type them; only the last four characters are shown.": "Las claves se cifran con una clave que permanece en el hardware seguro del teléfono y solo se envían a la dirección de su propio proveedor. La página no vuelve a verlas después de que las escribes; solo se muestran los últimos cuatro caracteres.",
