"Kilo Code is an open-source AI coding agent built as an editor extension (VS Code, JetBrains), not a phone terminal tool, so it does not chat here.": "Kilo Code es un agente de código con IA de código abierto creado como extensión de editor (VS Code, JetBrains), no una herramienta de terminal para el teléfono, así que no chatea aquí.",
