"Off": "Desactivado",
"Off by default": "Desactivado por defecto",
"Off:": "Desactivado:",
"Off: reading outside the current folder needs your OK.": "Desactivado: leer fuera de la carpeta actual requiere tu aprobación.",
"Off: the patches that work are applied and the failed ones are reported.": "Desactivado: se aplican los parches que funcionan y se informa de los que fallan.",
"Offer to delete the file afterwards": "Ofrecer eliminar el archivo después",
"Offline cache": "Caché sin conexión",
"Offline: showing what was loaded": "Sin conexión: se muestra lo que se cargó",
"Old": "Antiguo",
"Older version": "Versión anterior",
"Ollama": "Ollama",
"Ollama (on-device)": "Ollama (en el dispositivo)",
"Ollama is not running on this phone yet. Install it below, or enter the address of a computer that runs it.": "Ollama todavía no se está ejecutando en este teléfono. Instálalo abajo o ingresa la dirección de una computadora que lo ejecute.",
"Ollama runs a coding model right on this phone: free, and offline once the model is downloaded. It is installed in Termux; small models (1.5B to 3B) run best on a phone.": "Ollama ejecuta un modelo de código directamente en este teléfono: gratis y sin conexión una vez descargado el modelo. Se instala en Termux; los modelos pequeños (de 1.5B a 3B) funcionan mejor en un teléfono.",
"On": "Activado",
"On device": "En el dispositivo",
"On this phone": "En este teléfono",
"On:": "Activado:",
"One command at a time per shell; long output is trimmed on screen and in what is sent to an agent.": "Un comando a la vez por shell; la salida larga se recorta en pantalla y en lo que se envía a un agente.",
"One file only": "Un solo archivo",
"One key for the whole app. The Installer's scan and Morphe Helper's scan both use it; neither asks for it again, they only point here when it is missing.": "Una clave para toda la app. El análisis del Instalador y el de Morphe Helper la usan; ninguno la pide de nuevo, solo señalan aquí cuando falta.",
"One more place to find apps": "Un lugar más donde buscar apps",
"One package per line. Duplicate entries are removed automatically.": "Un paquete por línea. Las entradas duplicadas se eliminan automáticamente.",
"One source color, nine ways to turn it into a whole theme: the accent, the background, the cards and the text, in light and in dark. Choosing a style builds the theme from the source color below.": "Un color de origen, nueve formas de convertirlo en un tema completo: el acento, el fondo, las tarjetas y el texto, en claro y en oscuro. Elegir un estilo crea el tema a partir del color de origen de abajo.",
"Only AppCleaner uses it: it opens the system's App info screen of each app and taps Clear cache, for the caches no file access can reach. It does nothing else, never reads what is on the screen apart from those screens, and stops when the screen turns off.": "Solo lo usa AppCleaner: abre la pantalla Información de la app del sistema de cada app y toca Borrar caché, para las cachés a las que ningún acceso a archivos llega. No hace nada más, nunca lee lo que hay en pantalla aparte de esas pantallas y se detiene al apagarse la pantalla.",
"Only a marked block is written to these files; what you have in them stays, and running this again refreshes the block instead of adding another.": "En estos archivos solo se escribe un bloque marcado; lo que ya tengas en ellos se queda, y ejecutar esto de nuevo actualiza el bloque en lugar de añadir otro.",
"Only add sources you trust. A patch source decides what ends up inside your patched apps.": "Añade solo fuentes de confianza. Una fuente de parches decide qué acaba dentro de tus apps parcheadas.",
"Only apps installed on this phone": "Solo apps instaladas en este teléfono",
"Only base": "Solo base",
"Only hidden files are here. Tick Show hidden files to see them.": "Aquí solo hay archivos ocultos. Marca Mostrar archivos ocultos para verlos.",
"Only include common media files, documents and archives.": "Incluir solo archivos multimedia, documentos y archivos comprimidos comunes.",
"Only list what would run for each app. Nothing is run.": "Solo muestra lo que se ejecutaría para cada app. No se ejecuta nada.",
"Only patches for apps installed on this phone": "Solo parches de apps instaladas en este teléfono",
"Only text and compiled XML files can be compared line by line": "Solo se pueden comparar línea por línea los archivos de texto y los XML compilados",
"Only the lines written by the app you pick": "Solo las líneas escritas por la app que elijas",
"Only the selected apps are saved.": "Solo se guardan las apps seleccionadas.",
"Only the text of this app changes; names, paths and commands in code-style boxes keep their own font.": "Solo cambia el texto de esta app; los nombres, rutas y comandos en cuadros de código conservan su propia fuente.",
