"Perplexity": "Perplexity",
"Phone makers and apps add settings of their own.": "Los fabricantes de teléfonos y las apps añaden sus propios ajustes.",
"Pick a .mpp patch bundle from storage. A local source never updates on its own: pick the new file when one comes out.": "Elige un paquete de parches .mpp del almacenamiento. Una fuente local nunca se actualiza sola: elige el archivo nuevo cuando salga.",
"Pick a Coding Agent in the Terminal first": "Elige primero un agente de código en la Terminal",
"Pick a package file to read it and choose how to install it.": "Elige un archivo de paquete para leerlo y decidir cómo instalarlo.",
"Pick a package first": "Primero elige un paquete",
"Pick an agent under Coding Agents to chat": "Elige un agente en Agentes de código para chatear",
"Pick an agent, then the model and the effort (Low, Balanced or High: how hard it is asked to think). The first time, both start at a balanced choice, and the agent asks for what it needs (an API key, a server address, or a sign-in) and tests it before you start.": "Elige un agente y luego el modelo y el esfuerzo (Bajo, Equilibrado o Alto: cuánto se le pide que piense). La primera vez, ambos empiezan con una opción equilibrada, y el agente pide lo que necesita (una clave de API, una dirección de servidor o un inicio de sesión) y lo prueba antes de que empieces.",
"Pick at least one agent": "Elige al menos un agente",
"Pick at least one patch": "Elige al menos un parche",
"Pick one to fill the fields below, or write your own": "Elige uno para rellenar los campos de abajo, o escribe el tuyo",
"Pick which split APKs to install. The base APK is always included, and every other split starts ticked because \"Select all splits by default\" is on.": "Elige qué splits instalar. El APK base siempre se incluye y todos los demás splits empiezan marcados porque “Seleccionar todos los splits de forma predeterminada” está activado.",
"Pick which split APKs to install. The base APK is always included; the splits that fit this phone are ticked and the others are left off for you to add.": "Elige qué splits instalar. El APK base siempre se incluye; los splits que encajan con este teléfono están marcados y los demás quedan sin marcar para que los agregues.",
