"The Bluetooth link could not be set up.": "No se pudo configurar el enlace Bluetooth.",
"The Coding Agent that answers every Ask agent button: what a hidden setting, a permission, a process, a log line or an app is. Its key or sign-in is set up in the Command-Line Interface tab.": "El agente de código que responde a cada botón «Preguntar al agente»: qué es un ajuste oculto, un permiso, un proceso, una línea del registro o una app. Su clave o inicio de sesión se configura en la pestaña Línea de comandos.",
"The MCP button opens a sheet to give an agent extra tools (files, the web, a browser, GitHub...) through the Model Context Protocol. Pick a preset or write your own: a name, a local command or a remote address, and any key or header it needs. Pick which agents to add it to — the same server can go into two or more at once, since each agent keeps it in its own file.": "El botón MCP abre una hoja para dar a un agente herramientas adicionales (archivos, la web, un navegador, GitHub...) mediante el Model Context Protocol. Elige un preajuste o escribe el tuyo: un nombre, un comando local o una dirección remota, y la clave o el encabezado que necesite. Elige a qué agentes agregarlo: el mismo servidor puede ir a dos o más a la vez, ya que cada agente lo guarda en su propio archivo.",
"The Morphe engine is not in this build of the app": "El motor de Morphe no está en esta versión de la app",
"The PDF could not be shown.": "No se pudo mostrar el PDF.",
"The Rish shell ended. Tap Rish mode to open a new one.": "El shell de Rish terminó. Toca Modo Rish para abrir uno nuevo.",
"The Rish shell is no longer running.": "El shell de Rish ya no se está ejecutando.",
"The Terminal needs the app (it is not available in a plain browser)": "La Terminal necesita la app (no está disponible en un navegador normal)",
"The UAD-NG list has not been downloaded yet.": "La lista de UAD-NG aún no se ha descargado.",
"The UAD-NG list has nothing on this app": "La lista UAD-NG no tiene nada sobre esta app",
"The VirusTotal scan did not work": "El análisis de VirusTotal no funcionó",
"The accessibility service is not ready": "El servicio de accesibilidad no está listo",
"The accessibility service is not ready (it is not connected), so the caches that only it can clear stay. After this, use \"Clear the rest with accessibility\" on the AppCleaner card.": "El servicio de accesibilidad no está listo (no está conectado), así que las cachés que solo él puede borrar se quedan. Después, usa «Borrar el resto con accesibilidad» en la tarjeta de AppCleaner.",
"The accessibility service is not ready (it is off), so the caches that only it can clear stay. After this, use \"Clear the rest with accessibility\" on the AppCleaner card.": "El servicio de accesibilidad no está listo (está desactivado), así que las cachés que solo él puede borrar se quedan. Después, usa «Borrar el resto con accesibilidad» en la tarjeta de AppCleaner.",
"The accessibility service is not ready (no consent given), so the caches that only it can clear stay. After this, use \"Clear the rest with accessibility\" on the AppCleaner card.": "El servicio de accesibilidad no está listo (no se dio el consentimiento), así que las cachés que solo él puede borrar se quedan. Después, usa «Borrar el resto con accesibilidad» en la tarjeta de AppCleaner.",
"The account has no credit left, or a spending limit was reached.": "La cuenta se quedó sin crédito o se alcanzó un límite de gasto.",
"The agent is still working: STOP it first": "El agente sigue trabajando: toca STOP primero",
"The agent pauses after this many steps.": "El agente hace una pausa tras esta cantidad de pasos.",
"The app": "La app",
"The app is free, and it stays that way. If it saved you time, a coffee helps me keep improving it. Totally optional, and thank you!": "La app es gratis y seguirá siéndolo. Si te ahorró tiempo, un café me ayuda a seguir mejorándola. Es totalmente opcional, ¡y gracias!",
"The app version, Android version and phone model, so a problem is easier to find.": "La versión de la app, la versión de Android y el modelo del teléfono, para que sea más fácil encontrar el problema.",
"The apps you patch are listed here, with the log of each run, so you can install them again, share them or save them to Downloads.": "Aquí se listan las apps que parcheas, con el registro de cada ejecución, para que puedas instalarlas de nuevo, compartirlas o guardarlas en Descargas.",
"The archive file is rewritten without this file.": "El archivo comprimido se reescribe sin este archivo.",
"The archive file is rewritten without this folder and everything in it.": "El archivo comprimido se reescribe sin esta carpeta ni nada de lo que contiene.",
"The archive is deleted only when every file of it was extracted, with nothing skipped.": "El archivo comprimido solo se elimina si se extrajeron todos sus archivos, sin omitir ninguno.",
