"The patch bundle may be damaged or made for a newer Morphe. Update the source in Sources.": "El paquete de parches puede estar dañado o hecho para un Morphe más reciente. Actualiza la fuente en Fuentes.",
"The patched APK is only saved. Install it from Patched APKs.": "El APK parcheado solo se guarda. Instálalo desde APK parcheados.",
