"The patcher ran out of memory. Close other apps and try again, or turn on \"Strip unused native libraries\" in the patcher settings.": "Al parcheador se le acabó la memoria. Cierra otras apps e inténtalo de nuevo, o activa «Quitar bibliotecas nativas no usadas» en los ajustes del parcheador.",
"The patcher stopped": "El parcheador se detuvo",
