"The patches could not be read": "No se pudieron leer los parches",
"The patches do not support this version of the app. Get a supported version with Morphe Helper, or turn on \"Patch unsupported versions\" in the patcher settings.": "Los parches no admiten esta versión de la app. Consigue una versión compatible con Morphe Helper, o activa «Parchear versiones no compatibles» en los ajustes del parcheador.",
"The paths could not be read.": "No se pudieron leer las rutas.",
"The phone may still apply it. It is looked at again in a moment.": "Puede que el teléfono aún lo aplique. Se volverá a revisar en un momento.",
