"The phone's browser": "El navegador del teléfono",
"The project gives no description for this package.": "El proyecto no ofrece descripción para este paquete.",
"The providers do not support Android officially: the tool may not run on every phone. The Terminal shows its exact messages when something fails.": "Los proveedores no admiten Android oficialmente: puede que la herramienta no funcione en todos los teléfonos. La Terminal muestra sus mensajes exactos cuando algo falla.",
"The pull did not finish": "La descarga al teléfono no terminó",
