"The scan failed: unknown error": "Falló el análisis: error desconocido",
"The screen shows the settings of one app after the other for a moment while Clear cache is tapped for each app that still has a cache the files cannot reach. A cover shows what is happening, with a Cancel button. It stops if the screen turns off.": "La pantalla muestra un momento los ajustes de una app tras otra mientras se toca Borrar caché en cada app que aún tiene una caché a la que los archivos no llegan. Una cubierta muestra lo que ocurre, con un botón Cancelar. Se detiene si la pantalla se apaga.",
