"The service is switched on but has not connected yet; turn it off and on again in the accessibility settings.": "El servicio está activado pero aún no se ha conectado; desactívalo y actívalo de nuevo en los ajustes de accesibilidad.",
"The setting's name, table and current value are sent to them.": "Se les envía el nombre, la tabla y el valor actual del ajuste.",
"The shell did not start": "El shell no se inició",
