"The source could not be added": "No se pudo añadir la fuente",
"The sources that are on do not have patches yet, or the patch engine could not read them. Open Sources to update them.": "Las fuentes activadas aún no tienen parches, o el motor de parches no pudo leerlos. Abre Fuentes para actualizarlas.",
"The sources, Fast mode and VirusTotal flow of Morphe Helper follow": "Las fuentes, el Modo rápido y el flujo de VirusTotal de Morphe Helper siguen a",
"The store needs the app build (Android bridge).": "La tienda solo está disponible en la app (puente de Android).",
"The system colors are not available on this phone.": "Los colores del sistema no están disponibles en este teléfono.",
"The system colors could not be read here.": "No se pudieron leer aquí los colores del sistema.",
