"Then allow this app to \"Run commands in Termux environment\" and test the connection. Termux setup in the Terminal settings walks you through it.": "Luego concede a esta app “Run commands in Termux environment” y prueba la conexión. La opción Configuración de Termux de los Ajustes de la Terminal te guía paso a paso.",
"There are no saved lists to back up yet": "Aún no hay listas guardadas para copiar",
"There are no saved lists to back up yet; Restore works anyway.": "Aún no hay listas guardadas para copiar; Restaurar funciona igualmente.",
