"There is no undo.": "No se puede deshacer.",
"There is nothing to delete. Scan first.": "No hay nada que eliminar. Analiza primero.",
"These apps are currently selected for this action:": "Estas apps están seleccionadas para esta acción:",
"These apps are uninstalled but their data folders are still on the phone. The data of the apps you tick is deleted for good.": "Estas apps están desinstaladas pero sus carpetas de datos siguen en el teléfono. Los datos de las apps que marques se eliminan para siempre.",
"These apps are uninstalled. Without Root the app cannot see which of them still have data, so clearing all of them is safe but may find nothing for some. The data of the apps you tick is deleted for good.": "Estas apps están desinstaladas. Sin Root la app no puede ver cuáles aún tienen datos, así que borrar todas es seguro pero puede no encontrar nada en algunas. Los datos de las apps que marques se eliminan para siempre.",
"These apps' releases live on sites this app can't check directly. Obtainium can track them.": "Las versiones de estas apps están en sitios que esta app no puede verificar directamente. Obtainium puede hacerles seguimiento.",
"These files are too different to compare line by line. View each one instead.": "Estos archivos son demasiado distintos para compararlos línea por línea. Mejor visualiza cada uno.",
"They go on when the browser is closed. Pause keeps what was downloaded and Resume asks the site for the rest only (a site that cannot do that starts the file again).": "Continúan cuando se cierra el navegador. Pausar conserva lo descargado y Reanudar pide al sitio solo el resto (un sitio que no pueda hacerlo empieza el archivo de nuevo).",
"They will be skipped unless you patch anyway, which may fail or break the app.": "Se omitirán a menos que parchees de todos modos, lo que puede fallar o dañar la app.",
"Third-party packages only": "Solo paquetes de terceros",
"This App's ADB Key": "Clave ADB de esta app",
"This Shizuku version is too old. Please update Shizuku.": "Esta versión de Shizuku es demasiado antigua. Actualiza Shizuku.",
"This action cannot be undone.": "Esta acción no se puede deshacer.",
"This action needs access to files on this phone.": "Esta acción necesita acceso a los archivos de este teléfono.",
"This agent": "Este agente",
"This agent has no sign-in tool": "Este agente no tiene herramienta de inicio de sesión",
"This app": "Esta app",
"This app (sandbox)": "Esta app (sandbox)",
"This app cannot read storage. Grant All-files access, or choose a font file by hand (that needs no access).": "Esta app no puede leer el almacenamiento. Concede el acceso a todos los archivos o elige un archivo de fuente a mano (eso no requiere acceso).",
"This app does not ask for a particular touch screen, keyboard or navigation (it has no uses-configuration entry), so it runs with whatever this phone has.": "Esta app no pide una pantalla táctil, un teclado ni una navegación en particular (no tiene entrada uses-configuration), así que se ejecuta con lo que tenga este teléfono.",
"This app does not list any hardware or software features it needs (no uses-feature entries).": "Esta app no indica ninguna función de hardware o software que necesite (sin entradas uses-feature).",
"This app has no activities.": "Esta app no tiene actividades.",
"This app may not run commands in Termux yet.": "Puede que esta app aún no pueda ejecutar comandos en Termux.",
"This app now has its own private ADB key. Tap the mode badge for details.": "Esta app ahora tiene su propia clave ADB privada. Toca la insignia del modo para ver los detalles.",
"This app's code could not be read (it has none, or the file is not readable), so nothing can be said about trackers.": "No se pudo leer el código de esta app (no tiene, o el archivo no es legible), así que no se puede decir nada sobre rastreadores.",
"This app's own shell - no root, ADB or package manager.": "El shell propio de esta app: sin root, ADB ni gestor de paquetes.",
