"This build of the app does not contain the Morphe engine. Install a release build.": "Esta versión de la app no contiene el motor de Morphe. Instala una versión de lanzamiento.",
"This can cut the ADB connection this app uses, so you may not be able to change it back from here.": "Esto puede cortar la conexión ADB que usa esta app, por lo que quizá no puedas revertirlo desde aquí.",
