"This look is an old custom palette: choose a palette or a palette style first": "Este aspecto es una paleta personalizada antigua: elige antes una paleta o un estilo de paleta",
"This looks like a binary file. Pull it to this phone instead.": "Parece un archivo binario. Mejor tráelo a este teléfono.",
"This needs the app build.": "Esto solo está disponible en la app.",
"This only works with the agents that sign in through their own command-line tool in Termux (Claude Code, Gemini CLI, Codex, Copilot CLI, Cursor CLI, OpenCode); an agent used only with an API key cannot use one here.": "Esto solo funciona con los agentes que inician sesión mediante su propia herramienta de línea de comandos en Termux (Claude Code, Gemini CLI, Codex, Copilot CLI, Cursor CLI, OpenCode); un agente que se usa solo con una clave de API no puede usar uno aquí.",
"This package carries data files that live outside the APK. Right after the install succeeds they are copied into place.": "Este paquete incluye archivos de datos que están fuera del APK. Justo después de instalarse correctamente, se copian a su lugar.",
"This page is running without the app, so there is no phone to read the settings from.": "Esta página se ejecuta sin la app, así que no hay un teléfono del que leer los ajustes.",
"This phone": "Este teléfono",
"This phone has all of them.": "Este teléfono los tiene todos.",
"This phone has no Bluetooth.": "Este teléfono no tiene Bluetooth.",
"This phone is not connected to its own ADB. Turn on ADB in this app's Working mode first (Working Mode button at the top), then try again.": "Este teléfono no está conectado a su propio ADB. Activa primero ADB en el Modo de operación de esta app (botón Modo de operación, arriba) y vuelve a intentarlo.",
"This phone is not connected to its own ADB: turn on ADB in Working mode first.": "Este teléfono no está conectado a su propio ADB: activa antes ADB en el Modo de operación.",
"This phone lists no overlays.": "Este teléfono no muestra ningún overlay.",
