"This store needs the app build (Android bridge).": "Esta tienda solo está disponible en la app (puente de Android).",
"This version is not one the patches list. Patching may fail. Get a supported version with Morphe Helper, or patch anyway.": "Esta versión no figura entre las de los parches. El parcheo puede fallar. Consigue una versión compatible con Morphe Helper, o parchea de todos modos.",
