"Tip:": "Consejo:",
"To browse files on this phone, this app needs All-files access (or a working mode: ADB, Shizuku or Root).": "Para explorar los archivos de este teléfono, esta app necesita acceso a todos los archivos (o un modo de operación: ADB, Shizuku o Root).",
"To get an explanation, choose a default agent and connect it.": "Para obtener una explicación, elige un agente predeterminado y conéctalo.",
"To look in Downloads this app needs": "Para buscar en Descargas, esta app necesita",
"To make this the default installer, open any APK, choose this app, and tap \"Always\".": "Para que sea el instalador predeterminado, abre cualquier APK, elige esta app y toca “Siempre”.",
"To search storage for APK, APKS, APKM and XAPK files, this app needs All-files access (or a working mode: ADB, Shizuku or Root).": "Para buscar archivos APK, APKS, APKM y XAPK en el almacenamiento, esta app necesita acceso a todos los archivos (o un modo de operación: ADB, Shizuku o Root).",
"To search storage for fonts, this app needs All-files access. You can also choose a font file by hand, which needs no access.": "Para buscar fuentes en el almacenamiento, esta app necesita el acceso a todos los archivos. También puedes elegir un archivo de fuente a mano, lo que no requiere acceso.",
"To search storage, this app needs": "Para buscar en el almacenamiento, esta app necesita",
"To search the files on this phone, this app needs All-files access.": "Para buscar archivos en este teléfono, la app necesita acceso a todos los archivos.",
"To use DroidMind with an agent that speaks MCP (such as Claude Code or OpenCode), install it into the Debian container in Termux. Then start it with droidmind --transport sse and add it to that agent as an MCP server.": "Para usar DroidMind con un agente compatible con MCP (como Claude Code u OpenCode), instálalo en el contenedor Debian de Termux. Luego inícialo con droidmind --transport sse y agrégalo a ese agente como servidor MCP.",
