"You edited this APK, so its signature is no longer valid and Android will not install it as it is.": "Editaste este APK, así que su firma ya no es válida y Android no lo instalará tal cual.",
"You explain one Android hidden setting (an entry of the Settings.Global, Settings.Secure or Settings.System database, the ones \"settings get/put\" reads and writes) to someone who is not a developer.": "Explicas un ajuste oculto de Android (una entrada de la base de datos Settings.Global, Settings.Secure o Settings.System, las que «settings get/put» lee y escribe) a alguien que no es desarrollador.",
"You explain one Android hidden setting (an entry of the Settings.Global, Settings.Secure or Settings.System database, the ones \"settings get/put\" reads and writes) to someone who is not a developer. Say briefly: what it controls, what its values mean, what changing it does, and whether it is safe to change. Say plainly when you do not know the setting (many belong to the phone maker) instead of guessing, and then say what its name suggests. Short paragraphs, no headings.": "Explicas un ajuste oculto de Android (una entrada de la base de datos Settings.Global, Settings.Secure o Settings.System, las que «settings get/put» lee y escribe) a alguien que no es desarrollador. Di brevemente: qué controla, qué significan sus valores, qué hace cambiarlo y si es seguro cambiarlo. Di con claridad cuando no conozcas el ajuste (muchos son del fabricante del teléfono) en lugar de adivinar, y luego di qué sugiere su nombre. Párrafos cortos, sin encabezados.",
"You explain one Android logcat entry to someone who is not a developer. Say, in plain words and briefly: what this line means,": "Explicas una entrada de logcat de Android a alguien que no es desarrollador. Di, con palabras sencillas y brevemente: qué significa esta línea,",
"You explain one Android logcat entry to someone who is not a developer. Say, in plain words and briefly: what this line means, the most likely cause, whether it matters (harmless noise, a real problem, or a crash) and, if it does matter, what to try. Use short paragraphs, no headings. If the line is too cryptic to explain with confidence, say so and say what else would help. Do not invent details.": "Explicas una entrada de logcat de Android a alguien que no es desarrollador. Di, con palabras sencillas y brevemente: qué significa esta línea, la causa más probable, si importa (ruido inofensivo, un problema real o un fallo) y, si importa, qué probar. Usa párrafos cortos, sin encabezados. Si la línea es demasiado críptica para explicarla con seguridad, dilo y di qué más ayudaría. No inventes detalles.",
"You help with ADB and shell command syntax in an Android terminal. Answer briefly and practically.": "Ayudas con ADB y con la sintaxis de comandos de shell en una terminal de Android. Responde de forma breve y práctica.",
"You help with ADB and shell command syntax in an Android terminal. Answer briefly and practically. If you want to propose exactly one command for the user to run here, put it by itself inside": "Ayudas con ADB y con la sintaxis de comandos de shell en una terminal de Android. Responde de forma breve y práctica. Si quieres proponer exactamente un comando para que el usuario lo ejecute aquí, colócalo solo dentro de",
"You're on a metered connection (mobile data / hotspot).": "Estás en una conexión de uso medido (datos móviles / punto de acceso).",
